export const statesSalary: StateSalary[] = [
  { slug: "alabama", name: "Alabama", abbr: "AL", medianHousehold: 59609, medianIndividual: 32990, meanIndividual: 42530, costOfLivingIndex: 88, stateTaxRate: "2-5%", minWage: 7.25, topEmployers: ["Redstone Arsenal", "University of Alabama", "Huntsville Hospital"], topIndustries: ["Aerospace & Defense", "Automotive", "Healthcare"], intro: "Alabama's $59,609 median household income is well below the national average, but the cost-of-living index of 88 pulls effective purchasing power back toward the middle of the pack. The state's economy has changed meaningfully in the past twenty years. Huntsville, anchored by Redstone Arsenal and NASA Marshall Space Flight Center, has become one of the largest aerospace-and-defence employment clusters in the country — the city's median wages now exceed Atlanta's in several engineering categories. Further south, automotive manufacturing built by Mercedes-Benz, Hyundai, Honda, and Toyota has turned a crescent around Birmingham and Montgomery into a Tier-1 supplier hub. The state income tax is a simple three-bracket structure (2 to 5 percent), but Alabama is one of only three states that still allows a deduction for federal income taxes paid on state returns — an unusual feature that benefits higher earners disproportionately. The $7.25/hour minimum wage remains at the federal floor, and Alabama has no state minimum wage law on the books at all. Property taxes are among the lowest in the country (effective rates below 0.5%), which is part of why housing stays genuinely affordable statewide. Full income, employment, and tax breakdown follows." },
  { slug: "alaska", name: "Alaska", abbr: "AK", medianHousehold: 80287, medianIndividual: 39530, meanIndividual: 50820, costOfLivingIndex: 127, stateTaxRate: "0%", minWage: 11.73, topEmployers: ["State of Alaska", "Providence Health", "US Military"], topIndustries: ["Oil & Gas", "Fishing", "Federal Government"], intro: "Alaska has no state income tax and no state sales tax — a combination unique in the United States. What makes it more unusual still is the Permanent Fund Dividend, which pays every Alaska resident who has lived in the state for a full year an annual cash distribution from the state's oil-and-gas trust; that dividend has ranged from roughly $1,000 to $3,200 per person per year over the past decade. The structure funds a substantial share of the state budget and shifts the incentive economics of living here. The $80,287 median household income is above the national average, but the cost-of-living index of 127 erases most of that premium — Anchorage runs about 25% above the national average, and rural Alaska is dramatically higher because of freight costs. The economy concentrates in three sectors: oil and gas on the North Slope, commercial fishing (Alaska produces more than half of all wild-caught US seafood), and the federal government, which is one of the largest employers through the military and through federal land-management agencies. The $11.73/hour minimum wage is indexed to inflation. Property taxes vary widely by borough but run moderate on average. Data and calculators follow." },
  { slug: "arizona", name: "Arizona", abbr: "AZ", medianHousehold: 72581, medianIndividual: 36620, meanIndividual: 47340, costOfLivingIndex: 102, stateTaxRate: "2.5%", minWage: 14.35, topEmployers: ["Banner Health", "Walmart", "Arizona State University"], topIndustries: ["Technology", "Healthcare", "Tourism"], intro: "Arizona has one of the most aggressive income-tax reform stories of the past decade. The state converted from a four-bracket graduated tax to a flat 2.5% rate in 2023, ahead of the original phase-in schedule — making Arizona's income tax one of the lowest flat rates among states that tax income at all. The $72,581 median household income sits close to the national average, and the cost-of-living index of 102 is only marginally above it. The economy has pivoted sharply toward technology: TSMC's massive semiconductor fab complex in north Phoenix is expected to reach 6,000 employees at full build-out, Intel has expanded its Chandler campus repeatedly, and the entire Phoenix metro has become one of the fastest-growing tech-employment markets in the US. Banner Health is the state's largest private employer with over 50,000 staff, reflecting the outsized role healthcare plays driven in part by retiree in-migration. The $14.35/hour minimum wage is adjusted annually for inflation under Prop 206. Property taxes are below the national median. Water policy is the structural risk for the state's growth trajectory — Colorado River allocations and Central Arizona Project constraints are reshaping development timelines in the West Valley. Detailed breakdown follows." },
  { slug: "arkansas", name: "Arkansas", abbr: "AR", medianHousehold: 56335, medianIndividual: 30690, meanIndividual: 40110, costOfLivingIndex: 86, stateTaxRate: "2-4.7%", minWage: 11.00, topEmployers: ["Walmart", "Tyson Foods", "University of Arkansas"], topIndustries: ["Retail", "Agriculture", "Manufacturing"], intro: "Arkansas is the corporate home of Walmart — the world's largest private employer — and that single fact shapes more of the state's economy than any other variable. Bentonville and the surrounding Northwest Arkansas metro (Fayetteville, Rogers, Springdale) has become an unlikely Fortune 500 cluster: Tyson Foods and J.B. Hunt are both headquartered in the same metro, and Walmart's supplier ecosystem pulls dozens of large consumer-goods corporate offices into the region. The $56,335 median household income is well below the national average, but the cost-of-living index of 86 — 14% below the national baseline — means Arkansas consistently ranks as one of the most affordable states to live in. The state income tax was reduced multiple times between 2019 and 2024 and now tops out at 4.7%, with the bottom bracket at 2%. The $11/hour minimum wage is above the federal floor under a 2018 ballot initiative, placing Arkansas above neighbouring Mississippi, Louisiana, and Oklahoma on wage policy. Outside of Northwest Arkansas, the economy is more traditional — agriculture (rice and poultry, with Arkansas leading the US in both), manufacturing, and the logistics network around Little Rock. Property taxes are low. Full breakdown follows." },
  { slug: "california", name: "California", abbr: "CA", medianHousehold: 91905, medianIndividual: 43910, meanIndividual: 60200, costOfLivingIndex: 142, stateTaxRate: "1-13.3%", minWage: 16.00, topEmployers: ["University of California", "Kaiser Permanente", "State of California"], topIndustries: ["Technology", "Entertainment", "Agriculture"], intro: "California's $91,905 median household income is the fifth-highest in the country, but the headline hides one of the widest income gaps of any US state. A software engineer in Cupertino and a farmworker in Fresno County can both call California home while earning ten times apart. The cost-of-living index of 142 varies enormously by ZIP code too: a $90,000 salary in Bakersfield sustains a very different lifestyle than the same $90,000 in San Francisco, where the median rent on a one-bedroom hovers above $3,000. California's top marginal state income tax of 13.3% applies to incomes over $1 million (plus a 1% mental-health surcharge on the same bracket), making it the highest state income tax in the country. Below that threshold, the bracket structure is genuinely progressive — most earners pay between 4% and 9.3%. The $16/hour state minimum wage, with fast-food workers now earning $20/hour under AB 1228, also pushes the wage floor well above federal levels. The data and calculators below help you estimate take-home pay by region and industry." },
  { slug: "colorado", name: "Colorado", abbr: "CO", medianHousehold: 87598, medianIndividual: 43810, meanIndividual: 56120, costOfLivingIndex: 105, stateTaxRate: "4.4%", minWage: 14.42, topEmployers: ["UCHealth", "Lockheed Martin", "University of Colorado"], topIndustries: ["Technology", "Aerospace", "Tourism"], intro: "Colorado's $87,598 median household income is among the top ten in the US, and the state has been one of the fastest-growing destinations for tech and aerospace professionals over the past decade. Denver, Boulder, and Colorado Springs form a corridor that anchors the economy: Boulder's biotech and outdoor-industry clusters, Denver's finance and telecom employers (Charles Schwab, Lumen), and Colorado Springs' dense aerospace footprint (Lockheed Martin, Northrop, and Space Force HQ). The cost-of-living index of 105 is modestly above the national average, but Front Range housing costs have risen sharply — Denver and Boulder both consistently rank in the top twenty most expensive US metros by median home price. The state income tax is a flat 4.4%, one of the lower flat rates in the country. The $14.42/hour minimum wage is indexed to inflation, and Denver's local minimum pushes above $18. TABOR (the Taxpayer's Bill of Rights) constrains state revenue growth and often triggers taxpayer refunds in strong revenue years — a mechanism unique among US states. The Western Slope (Grand Junction and the mountain towns) operates as a separate economy driven by tourism, agriculture, and energy. Full salary and employment detail follows." },
  { slug: "connecticut", name: "Connecticut", abbr: "CT", medianHousehold: 90213, medianIndividual: 45230, meanIndividual: 60150, costOfLivingIndex: 113, stateTaxRate: "3-6.99%", minWage: 16.35, topEmployers: ["Yale New Haven Health", "Hartford HealthCare", "Raytheon"], topIndustries: ["Finance & Insurance", "Healthcare", "Manufacturing"], intro: "Connecticut's $90,213 median household income is among the top ten in the US, a reflection of both the Fairfield County commuter belt into New York City and the Hartford insurance-and-finance corridor. The state's two economies are stark. Fairfield County (Stamford, Greenwich, Darien) has some of the highest household incomes in the country, driven by hedge-fund and asset-management employment; the Hartford region is dominated by insurance giants (The Hartford, Travelers, Aetna/CVS Health) and was historically the insurance capital of the US. The eastern part of the state has a different economy entirely — Electric Boat in Groton manufactures nuclear submarines and is one of the largest private employers in New England. The cost-of-living index of 113 reflects housing costs that run 30 to 50 percent above the national average in Fairfield County. State income tax brackets range from 3% to 6.99%, and Connecticut is one of a handful of states that imposes an estate tax. The $16.35/hour minimum wage is among the highest in the country and is adjusted annually. Property taxes are the second-highest in the US by effective rate, behind only New Jersey. Detailed salary, cost-of-living, and employer data follow." },
  { slug: "delaware", name: "Delaware", abbr: "DE", medianHousehold: 79325, medianIndividual: 38710, meanIndividual: 50340, costOfLivingIndex: 103, stateTaxRate: "2.2-6.6%", minWage: 13.25, topEmployers: ["ChristianaCare", "DuPont", "Bank of America"], topIndustries: ["Finance", "Chemical Manufacturing", "Healthcare"], intro: "Delaware punches far above its size in the US economy because of corporate law: more than 60% of Fortune 500 companies and roughly 80% of US IPOs are incorporated in Delaware, primarily because of the Court of Chancery and a highly specialised body of business precedent. That statutory infrastructure funds a large share of the state budget through franchise-tax revenue rather than personal income tax. The $79,325 median household income is above the national average, and the cost-of-living index of 103 is only slightly above baseline. New Castle County in the north (Wilmington, Newark) anchors the economy — Bank of America, JPMorgan Chase, and Barclays all run major operations there, and DuPont's historic chemicals footprint (along with successor entities DuPont de Nemours, Corteva, and Chemours) remains economically significant. The southern two counties (Kent and Sussex) have a very different economy driven by poultry (Perdue and Mountaire), tourism along the Atlantic beaches, and retiree in-migration. State income tax ranges from 2.2% to 6.6%. Delaware is one of just five states with no sales tax. The $13.25/hour minimum wage is above the federal floor and indexed. Detailed data follows." },
  { slug: "florida", name: "Florida", abbr: "FL", medianHousehold: 67917, medianIndividual: 35820, meanIndividual: 48130, costOfLivingIndex: 103, stateTaxRate: "0%", minWage: 13.00, topEmployers: ["Walt Disney World", "AdventHealth", "Publix"], topIndustries: ["Tourism", "Healthcare", "Real Estate"], intro: "Florida's $67,917 median household income sits below the national median, yet the state has been among the top three destinations for domestic in-migration every year since 2019. The pull is structural: no state income tax, no estate tax, a constitutionally capped homestead property-tax increase, and a sunbelt climate that extends the tourism economy year-round. The catch, for most residents, is that wage levels haven't kept pace with the cost of housing. Florida's cost-of-living index of 103 slightly exceeds the national average, and that figure masks how concentrated the increase has been in housing specifically since 2020. Miami, Tampa, Orlando, and Jacksonville metros have all seen median home prices rise 40 to 60 percent since 2019. The $13 state minimum wage is already above the federal floor and is scheduled to reach $15 by September 2026 under a constitutional amendment voters passed in 2020. Florida's economy leans heavily on tourism (Walt Disney World and the cruise-port complex), healthcare (AdventHealth is one of the largest non-profit systems in the US), agriculture (citrus and sugar), and an outsized retiree-services industry. Salary data, cost-of-living context, and tax information for Florida residents are broken down below." },
  { slug: "georgia", name: "Georgia", abbr: "GA", medianHousehold: 71355, medianIndividual: 35510, meanIndividual: 47020, costOfLivingIndex: 93, stateTaxRate: "1-5.49%", minWage: 7.25, topEmployers: ["Delta Air Lines", "Home Depot", "UPS"], topIndustries: ["Logistics", "Technology", "Film & Entertainment"], intro: "Georgia's $71,355 median household income has grown steadily for a decade, outpacing most of the South and putting the state ahead of neighbours Alabama, South Carolina, and Tennessee. The economy has three distinct engines. Atlanta's logistics cluster is anchored by the world's busiest airport (Hartsfield-Jackson) and by UPS and Delta headquarters. An unusually large film and television production industry grew out of the 30% tax credit the state introduced in 2008, making Georgia the top US filming state for studio features by the late 2010s. And a technology footprint has pulled Microsoft, Google, and NCR into midtown Atlanta over the past five years. Outside the metro, the economy is more traditional — agriculture (peanuts, poultry, cotton), manufacturing, and port-adjacent logistics around Savannah. The state income tax was converted to a flat rate in 2024, now sitting at 5.39% with further scheduled reductions toward 4.99% by 2028. The $7.25/hour minimum wage remains at the federal floor. Georgia is technically one of only five states with a state minimum wage below the federal rate (its state minimum is still $5.15 on the books), though the federal rate applies to nearly all employers in practice. Detailed breakdown follows." },
  { slug: "hawaii", name: "Hawaii", abbr: "HI", medianHousehold: 94814, medianIndividual: 40420, meanIndividual: 51680, costOfLivingIndex: 192, stateTaxRate: "1.4-11%", minWage: 14.00, topEmployers: ["US Military", "State of Hawaii", "Hawaiian Airlines"], topIndustries: ["Tourism", "Military", "Agriculture"], intro: "Hawaii has the highest cost-of-living index in the country at 192 — nearly double the national average — a direct consequence of geography: nearly everything consumed in the state has to be shipped in from 2,400 miles away or farther. That single fact distorts nearly every economic metric. The $94,814 median household income is among the top five in the US, but in purchasing-power terms Hawaii's effective median is closer to Mississippi's. Honolulu has consistently ranked as one of the least affordable major housing markets in the country — median single-family home prices in the core of Oahu exceed $1 million. The economy is dominated by three sectors: tourism (the single largest private-sector employer cluster), the US military (roughly 50,000 active-duty service members plus civilian contractors, making Hawaii one of the largest federal footprints per capita in the country), and agriculture (macadamia nuts, coffee, tropical fruit, much of it export-focused). State income tax has the second-highest top marginal rate in the country at 11%, with an unusually progressive seven-bracket structure. The $14/hour minimum wage is indexed and scheduled to reach $18 by 2028. Full breakdown follows." },
  { slug: "idaho", name: "Idaho", abbr: "ID", medianHousehold: 74942, medianIndividual: 33390, meanIndividual: 43210, costOfLivingIndex: 97, stateTaxRate: "5.695%", minWage: 7.25, topEmployers: ["St. Luke's Health", "Micron Technology", "Boise State University"], topIndustries: ["Technology", "Agriculture", "Manufacturing"], intro: "Idaho has been one of the fastest-growing states in the US over the past decade by percentage, and the Boise metro specifically has led that growth. The $74,942 median household income has climbed meaningfully from the mid-2010s as the state's technology footprint expanded. Micron Technology, one of the largest memory-chip manufacturers in the world, is headquartered in Boise and is the state's largest private employer; its recent $15 billion fab expansion is expected to add thousands of high-wage jobs over the next decade. Outside of Boise, the economy is more traditional — agriculture (potatoes, dairy, sugar beets, wheat), manufacturing, and tourism around the mountain regions. The cost-of-living index of 97 sits just below the national average, but Boise's housing market has decoupled from that statewide figure; median home prices in Ada County have roughly doubled since 2016. Idaho's flat state income tax of 5.695% is among the higher flat rates in the West. The $7.25/hour minimum wage remains at the federal floor, and bills to raise it have stalled repeatedly in the legislature. Property taxes are modest by national standards. Full data follows." },
  { slug: "illinois", name: "Illinois", abbr: "IL", medianHousehold: 78433, medianIndividual: 39790, meanIndividual: 52610, costOfLivingIndex: 93, stateTaxRate: "4.95%", minWage: 14.00, topEmployers: ["University of Chicago", "Abbott Labs", "Boeing"], topIndustries: ["Finance", "Manufacturing", "Technology"], intro: "Illinois's $78,433 median household income ranks in the upper half of US states, but the state's story over the last decade has been defined by slow outmigration — Illinois has lost population almost every year since 2014. Chicago anchors the economy and holds most of the high-income jobs, while much of downstate Illinois has closer economic ties to the Rust Belt than to the finance-and-tech cluster in the Loop. The flat 4.95% state income tax is unusual for a state of Illinois's size; a 2020 referendum that would have replaced it with graduated brackets failed at the ballot box, leaving the flat rate in place. Property taxes are among the highest in the country — effective rates above 2% in Cook County — and that single fact explains much of the outmigration. The $14/hour minimum wage is well above the federal floor and is indexed to reach $15 on the schedule set by the 2019 Lifting Up Illinois Working Families Act. Chicago remains one of the largest financial hubs in the country outside New York, with the CME Group, major bank back-offices, and a growing private-equity footprint. Manufacturing (Caterpillar, Deere) and healthcare (University of Chicago Medicine, Rush, Northwestern Medicine) round out the top industries. Breakdown follows." },
  { slug: "indiana", name: "Indiana", abbr: "IN", medianHousehold: 67173, medianIndividual: 33960, meanIndividual: 43530, costOfLivingIndex: 90, stateTaxRate: "3.05%", minWage: 7.25, topEmployers: ["Indiana University Health", "Eli Lilly", "Salesforce"], topIndustries: ["Manufacturing", "Healthcare", "Agriculture"], intro: "Indiana has one of the lowest flat-rate state income taxes in the country at 3.05%, and a multi-year schedule will reduce it further to 2.9% by 2027 under legislation enacted in 2023. That tax structure, combined with a cost-of-living index of 90, is part of why the state consistently ranks as one of the most affordable places to live in the Midwest. The $67,173 median household income is below the national average, but effective purchasing power ranks well. The economy is a rare example of manufacturing strength that survived the 2000s intact: auto and parts manufacturing, RV production (Elkhart County produces over 80% of all RVs made in the US), and steel (the Gary–Hammond corridor still operates major US Steel and Cleveland-Cliffs mills). Eli Lilly, one of the largest pharmaceutical companies in the world, is headquartered in Indianapolis and is the state's largest private employer. Salesforce anchors a fast-growing tech-employment cluster in downtown Indianapolis. The $7.25/hour minimum wage remains at the federal floor. Counties also levy local income taxes ranging from roughly 0.5% to 3%, adding meaningfully to total tax burden depending on location. Full breakdown follows." },
  { slug: "iowa", name: "Iowa", abbr: "IA", medianHousehold: 72429, medianIndividual: 35100, meanIndividual: 44210, costOfLivingIndex: 90, stateTaxRate: "3.8%", minWage: 7.25, topEmployers: ["University of Iowa", "UnityPoint Health", "Principal Financial"], topIndustries: ["Agriculture", "Manufacturing", "Finance"], intro: "Iowa completed a major income-tax reform between 2022 and 2025 that consolidated the state's bracket structure into a flat 3.8% rate — one of the lowest flat rates in the country. That puts Iowa's tax burden well below most Midwestern neighbours. The $72,429 median household income is slightly above the national average, and the cost-of-living index of 90 translates to real purchasing power at the upper end of the Midwest. The economy is more diverse than the agriculture-dominant image suggests: Des Moines has become one of the largest insurance and financial-services hubs in the country, anchored by Principal Financial Group (Fortune 500), Nationwide's major campus, and Wells Fargo's largest employee site outside of its San Francisco headquarters. Agriculture (corn, soy, pork — Iowa leads the US in all three) and manufacturing (John Deere in Waterloo, Collins Aerospace in Cedar Rapids) fill out the other main employment clusters. The $7.25/hour minimum wage remains at the federal floor. Property taxes have been trending down after a 2023 reform that tightened assessment growth. Iowa has no estate or inheritance tax as of 2025 (the inheritance tax phased out under earlier reforms). Full breakdown follows." },
  { slug: "kansas", name: "Kansas", abbr: "KS", medianHousehold: 69747, medianIndividual: 35090, meanIndividual: 44800, costOfLivingIndex: 89, stateTaxRate: "3.1-5.7%", minWage: 7.25, topEmployers: ["Spirit AeroSystems", "University of Kansas", "Sprint/T-Mobile"], topIndustries: ["Aviation", "Agriculture", "Healthcare"], intro: "Kansas is the centre of the US aviation industry by manufacturing output — Wichita has produced the majority of general-aviation aircraft in the country for decades, with Spirit AeroSystems (Boeing's largest supplier), Textron Aviation (Cessna, Beechcraft, Hawker), and Bombardier Learjet all operating major plants in the metro. The $69,747 median household income is close to the national average, and the cost-of-living index of 89 — 11% below the national baseline — gives Kansas households among the strongest effective purchasing power in the country. Agriculture (wheat, sorghum, cattle — Kansas is the largest wheat-producing state) and healthcare fill out the other two main employment clusters. The state income tax has three brackets (3.1% to 5.7%) and has been the subject of repeated policy debate since the failed 2012 tax experiment under Governor Brownback; the current structure represents a more gradual, solvency-focused approach. The $7.25/hour minimum wage remains at the federal floor. Kansas City on the Kansas side is economically integrated with its Missouri-side counterpart, which makes local tax and employment figures harder to interpret without looking at the metro as a whole. Full data follows." },
  { slug: "kentucky", name: "Kentucky", abbr: "KY", medianHousehold: 60407, medianIndividual: 31730, meanIndividual: 42010, costOfLivingIndex: 90, stateTaxRate: "4.5%", minWage: 7.25, topEmployers: ["UPS WorldPort", "Humana", "University of Kentucky"], topIndustries: ["Logistics", "Healthcare", "Manufacturing"], intro: "Kentucky's $60,407 median household income is below the national average, but the cost-of-living index of 90 means effective purchasing power is closer to the middle of the US pack. The state's economy is anchored by three unusual pieces of infrastructure: UPS WorldPort in Louisville — the largest automated package-handling facility in the world, sorting over two million packages per day — Toyota Motor Manufacturing Kentucky in Georgetown (the company's largest vehicle-production plant globally), and the bourbon-distilling industry (Kentucky produces roughly 95% of the world's bourbon). Louisville and Lexington are the primary economic centres; Louisville's healthcare cluster, led by Humana, is among the largest in the South. The state income tax was a flat 4.5% and is scheduled to continue stepping down toward 4% under enacted law tied to revenue triggers. The $7.25/hour minimum wage remains at the federal floor. Eastern Kentucky (the coal-producing Appalachian counties) has a very different economy; employment has declined sharply over the past two decades as coal demand has contracted. Property taxes are low. Full income, tax, and employer breakdown follows." },
  { slug: "louisiana", name: "Louisiana", abbr: "LA", medianHousehold: 57852, medianIndividual: 31530, meanIndividual: 42800, costOfLivingIndex: 91, stateTaxRate: "1.85-4.25%", minWage: 7.25, topEmployers: ["Ochsner Health", "LCMC Health", "Entergy"], topIndustries: ["Oil & Gas", "Healthcare", "Tourism"], intro: "Louisiana's $57,852 median household income is one of the lowest in the US, and the state has struggled with out-migration since Hurricane Katrina in 2005 reshaped New Orleans' population and workforce. The cost-of-living index of 91 pulls effective purchasing power back toward the middle, but the structural challenges are real — median wages have grown more slowly than most of the South over the past two decades. The economy is heavily weighted toward the oil-and-gas value chain (refining and petrochemicals along the Mississippi River corridor between Baton Rouge and New Orleans), healthcare (Ochsner Health is the largest private employer in the state), and tourism concentrated in New Orleans. The port of New Orleans and the adjacent Plaquemines and St. Bernard port terminals together form one of the largest port complexes in the Western Hemisphere. State income tax was reformed to a simpler structure ranging from 1.85% to 4.25%, and a 2024 overhaul is reducing it further toward a flat 3% in 2025. The $7.25/hour minimum wage remains at the federal floor, one of roughly twenty states still at that level. Property taxes are among the lowest in the country. Full breakdown follows." },
  { slug: "maine", name: "Maine", abbr: "ME", medianHousehold: 68251, medianIndividual: 35830, meanIndividual: 45020, costOfLivingIndex: 113, stateTaxRate: "5.8-7.15%", minWage: 14.15, topEmployers: ["MaineHealth", "Hannaford", "L.L. Bean"], topIndustries: ["Healthcare", "Tourism", "Fishing"], intro: "Maine has the oldest median age of any US state, and that demographic fact shapes its economy in ways the income numbers alone don't capture. The $68,251 median household income is below the national average, but the cost-of-living index of 113 pushes effective purchasing power further down — Maine is meaningfully more expensive than its wage levels suggest, driven by heating-oil costs, grocery prices in rural areas, and rising housing costs that have accelerated since 2020 as remote workers relocated from Boston and New York. The economy has three pillars: healthcare (MaineHealth and Northern Light Health together dominate statewide employment), tourism concentrated on the coast between Kennebunkport and Bar Harbor, and the commercial fishing industry (Maine produces over 80% of US lobster by weight). Portland has been the fastest-growing metro of the past decade; Bangor and more rural counties have seen much slower growth. The $14.15/hour minimum wage is indexed to inflation and is among the highest wage floors in the Northeast. State income tax ranges from 5.8% to 7.15% across three brackets. Property taxes run moderate. L.L. Bean's Freeport headquarters continues to anchor the mid-coast economy. Full data follows." },
  { slug: "maryland", name: "Maryland", abbr: "MD", medianHousehold: 98461, medianIndividual: 44880, meanIndividual: 58330, costOfLivingIndex: 120, stateTaxRate: "2-5.75%", minWage: 15.00, topEmployers: ["Johns Hopkins", "NIH", "Fort Meade/NSA"], topIndustries: ["Federal Government", "Healthcare", "Cybersecurity"], intro: "Maryland has the highest median household income of any US state at $98,461 — a number driven primarily by the federal workforce and its contractor ecosystem in the DC metro. The concentration of federal-adjacent employment in Montgomery, Prince George's, and Anne Arundel counties — NIH in Bethesda, the NSA and US Cyber Command at Fort Meade, and hundreds of defence and IT contractors — has produced one of the densest high-income professional clusters in the country. Baltimore operates as a separate economy, anchored by Johns Hopkins (the largest private employer in the state, with both its academic medical system and its Applied Physics Laboratory) and by the port of Baltimore, which handles more roll-on/roll-off automobile traffic than any other US port. The cost-of-living index of 120 — 20% above the national average — largely reflects Montgomery County's housing market. State income tax ranges from 2% to 5.75%, and counties layer on local income taxes of 2.25% to 3.2% that push the effective top rate close to 9%. The $15/hour minimum wage is indexed with step-ups. Property taxes are moderate. Maryland has both an estate tax and an inheritance tax. Full breakdown follows." },
  { slug: "massachusetts", name: "Massachusetts", abbr: "MA", medianHousehold: 96505, medianIndividual: 48050, meanIndividual: 64280, costOfLivingIndex: 135, stateTaxRate: "5% + 4% surtax on >$1M", minWage: 15.00, topEmployers: ["Mass General Brigham", "Harvard", "MIT"], topIndustries: ["Biotech", "Technology", "Education"], intro: "Massachusetts's $96,505 median household income is among the top three in the country, driven by the highest concentration of biotech, pharmaceutical, and research-university employment in the US. The Kendall Square cluster in Cambridge is arguably the densest biotech ecosystem in the world — the top ten pharma companies all maintain major R&D operations there, and the cluster is anchored by MIT and Harvard. Mass General Brigham is the largest private employer in the state, and healthcare-and-research employment together accounts for a disproportionate share of high-wage jobs. The cost-of-living index of 135 is driven overwhelmingly by Greater Boston housing costs, which have diverged sharply from central and western Massachusetts (Springfield, Worcester). The state income tax is a flat 5%, but voters approved a 4% surtax on income over $1 million in 2022 (the Fair Share Amendment) — the first progressive adjustment to the state's flat tax in over a century. The $15/hour minimum wage applies statewide. Property taxes are moderate by Northeast standards. Massachusetts has a large and uniquely comprehensive state healthcare programme dating to the 2006 Romney-era reform that inspired the ACA. Full data follows." },
  { slug: "michigan", name: "Michigan", abbr: "MI", medianHousehold: 66986, medianIndividual: 34650, meanIndividual: 45520, costOfLivingIndex: 90, stateTaxRate: "4.25%", minWage: 10.56, topEmployers: ["University of Michigan", "Ford", "General Motors"], topIndustries: ["Automotive", "Healthcare", "Manufacturing"], intro: "Michigan's economy is still defined by the auto industry, but the story is more nuanced than the Big Three headlines suggest. Ford, General Motors, and Stellantis (formerly Fiat Chrysler) remain three of the largest private employers, but the state's real employment engine for most of the past two decades has been healthcare. The University of Michigan health system alone employs over 30,000 people, and Corewell Health (the 2022 merger of Beaumont and Spectrum), Henry Ford Health, and Trinity Health Michigan are each among the top ten private employers statewide. The $66,986 median household income is below the national average, but the cost-of-living index of 90 means dollars go 10% further than the US baseline. Grand Rapids, on the western side of the state, has quietly become a furniture-manufacturing and healthcare hub with costs meaningfully below Metro Detroit. The flat 4.25% state income tax is among the lowest in the Great Lakes region, and Michigan has no local income tax in most cities (Detroit, Grand Rapids, and a few others are the exceptions). The $10.56/hour minimum wage sits above the federal floor and is adjusted annually. Property taxes run near the national median. Full salary and employment data follow." },
  { slug: "minnesota", name: "Minnesota", abbr: "MN", medianHousehold: 84313, medianIndividual: 41710, meanIndividual: 53920, costOfLivingIndex: 97, stateTaxRate: "5.35-9.85%", minWage: 11.13, topEmployers: ["Mayo Clinic", "UnitedHealth Group", "Target"], topIndustries: ["Healthcare", "Finance", "Retail"], intro: "Minnesota has an unusually concentrated corporate base for a state of its size: sixteen Fortune 500 companies are headquartered there (including UnitedHealth Group, Target, 3M, Best Buy, US Bancorp, and General Mills), the third-highest per capita of any state. The $84,313 median household income is among the top fifteen in the US, supported by that corporate cluster and by the Twin Cities' broader professional-services economy. The Mayo Clinic in Rochester is one of the most significant single employers in the state and the anchor of what has become the largest single-specialty healthcare cluster in the world. The cost-of-living index of 97 sits just below the national average, which combined with high incomes gives Minnesota one of the strongest effective purchasing-power profiles in the country. The state income tax is progressive with four brackets ranging from 5.35% to 9.85%. The $11.13/hour minimum wage varies by employer size and is indexed to inflation; Minneapolis and Saint Paul have local ordinances that push their city minimums above the state level. Property taxes are moderate. Greater Minnesota (outside the Twin Cities) has a more agriculture- and mining-dependent economy. Full breakdown follows." },
  { slug: "mississippi", name: "Mississippi", abbr: "MS", medianHousehold: 52985, medianIndividual: 28990, meanIndividual: 38120, costOfLivingIndex: 84, stateTaxRate: "0-5%", minWage: 7.25, topEmployers: ["University of Mississippi Medical", "Walmart", "Nissan"], topIndustries: ["Agriculture", "Manufacturing", "Healthcare"], intro: "Mississippi has the lowest median household income of any US state at $52,985 and the lowest cost-of-living index at 84, which partially — though not fully — offsets the wage gap in purchasing-power terms. The state has struggled with population loss, outmigration of college graduates, and persistent underinvestment in public infrastructure for most of the past two decades. The economy is weighted toward agriculture (cotton, soybeans, poultry, catfish — Mississippi produces more farm-raised catfish than any other state), manufacturing (Nissan's Canton plant and Toyota's Blue Springs plant are anchor employers), and healthcare (the University of Mississippi Medical Center in Jackson is the largest single employer in the state). The Gulf Coast has a separate economy driven by casinos, shipbuilding at Ingalls in Pascagoula (one of the largest defence-shipbuilders in the US), and tourism. State income tax is a flat 5% above an exemption threshold, and is scheduled to step down toward 4% and ultimately zero under recent legislation, though the pace depends on revenue triggers. The $7.25/hour minimum wage remains at the federal floor, with no state minimum wage law on the books. Full data follows." },
  { slug: "missouri", name: "Missouri", abbr: "MO", medianHousehold: 65920, medianIndividual: 34430, meanIndividual: 44680, costOfLivingIndex: 89, stateTaxRate: "2-4.95%", minWage: 12.80, topEmployers: ["BJC HealthCare", "Cerner", "Washington University"], topIndustries: ["Healthcare", "Manufacturing", "Financial Services"], intro: "Missouri has two major metros that operate as effectively independent economies: Kansas City (split with the Kansas side of the state line) and St. Louis. The $65,920 median household income is below the national average, but the cost-of-living index of 89 — among the ten lowest in the country — gives Missouri households solid effective purchasing power. The St. Louis economy is anchored by healthcare and research (BJC HealthCare, Washington University, Saint Louis University), by agribusiness (Bayer Crop Science's US headquarters, formerly Monsanto), and by a diverse manufacturing base. Kansas City's economy spans logistics (one of the largest rail hubs in the US), engineering (Burns & McDonnell is headquartered there), and animal-health pharma (the Animal Health Corridor between KC and Manhattan, KS, is the largest concentration of veterinary pharma employment in the world). State income tax tops out at 4.95% and has been reduced in multiple rounds since 2014. The $12.80/hour minimum wage is indexed annually under a 2018 ballot initiative. Property taxes run moderate. Missouri has no estate or inheritance tax. Full salary and employment breakdown follows." },
  { slug: "montana", name: "Montana", abbr: "MT", medianHousehold: 66017, medianIndividual: 34140, meanIndividual: 43370, costOfLivingIndex: 99, stateTaxRate: "1-6.75%", minWage: 10.55, topEmployers: ["Benefis Health", "University of Montana", "Billings Clinic"], topIndustries: ["Agriculture", "Tourism", "Energy"], intro: "Montana's $66,017 median household income is below the national average, but the state has seen sharp income growth over the past five years as remote workers have relocated to Bozeman, Missoula, and the Bitterroot Valley. The cost-of-living index of 99 is roughly at the national average, though Bozeman specifically has become dramatically more expensive — median home prices there have more than doubled since 2017, outpacing wage growth. The economy is a mix of agriculture (wheat, cattle — Montana has more cattle than people by a wide margin), tourism (Glacier and Yellowstone parks anchor the north and south), energy (oil in the Williston Basin, coal in the southeast, wind across the east), and a federal-employment footprint (Malmstrom AFB, federal land management). State income tax brackets range from 1% to 6.75% across seven brackets, one of the more progressive structures in the West. The $10.55/hour minimum wage is indexed to inflation. Property taxes have been rising quickly because of accelerating housing values, and a 2023 reassessment triggered statewide political pushback. Montana has no sales tax. Full breakdown follows." },
  { slug: "nebraska", name: "Nebraska", abbr: "NE", medianHousehold: 74580, medianIndividual: 36200, meanIndividual: 45710, costOfLivingIndex: 91, stateTaxRate: "2.46-5.84%", minWage: 13.50, topEmployers: ["Nebraska Medicine", "Mutual of Omaha", "Union Pacific"], topIndustries: ["Agriculture", "Insurance", "Transportation"], intro: "Nebraska's $74,580 median household income is above the national average, and the cost-of-living index of 91 gives the state one of the stronger effective purchasing-power positions in the Midwest. Omaha anchors the economy as one of the largest insurance markets in the country — Mutual of Omaha and Berkshire Hathaway are both headquartered there, and Union Pacific's headquarters employs thousands more. Warren Buffett's Berkshire has made the city an unlikely centre of investment-management employment for a metro of its size. Lincoln, the state capital and home to the University of Nebraska, anchors a smaller but faster-growing economy driven by the university and by a software-and-services sector that has emerged over the past decade (Hudl, Spreetail, Bulu Group). Outside the two metros, the economy is dominated by agriculture — Nebraska consistently ranks first or second in corn and cattle production. State income tax brackets range from 2.46% to 5.84% and are scheduled to reduce further under enacted law. The $13.50/hour minimum wage was raised via ballot initiative in 2022 and is stepping up to $15 by 2026. Property taxes are high and have been the central issue in state politics. Full data follows." },
  { slug: "nevada", name: "Nevada", abbr: "NV", medianHousehold: 69187, medianIndividual: 35680, meanIndividual: 46230, costOfLivingIndex: 104, stateTaxRate: "0%", minWage: 12.00, topEmployers: ["MGM Resorts", "Wynn Resorts", "Clark County School District"], topIndustries: ["Tourism & Gaming", "Mining", "Technology"], intro: "Nevada has no state income tax, a fact rooted in the state's gaming-tax structure — casino revenue taxes fund a disproportionate share of the state budget, insulating general income from direct taxation. The $69,187 median household income is close to the national average, and the cost-of-living index of 104 is only marginally above. Las Vegas and Reno dominate the economy: Clark County (Las Vegas metro) contains roughly three-quarters of the state's population and most of the gaming-and-hospitality employment. MGM Resorts, Wynn, Caesars, and Las Vegas Sands together employ a substantial fraction of the metro's workforce. Reno has quietly become a logistics and manufacturing hub — Tesla's Gigafactory in Sparks is one of the largest lithium-ion battery facilities in the world, and Amazon, Apple, and Switch all maintain major data-centre campuses in the region. Mining remains significant in the rural north — Nevada is the largest gold-producing state in the US by a wide margin. The $12/hour minimum wage varies by employer health-benefit status under state law. Property taxes are modest. Full salary and employment breakdown follows." },
  { slug: "new-hampshire", name: "New Hampshire", abbr: "NH", medianHousehold: 90845, medianIndividual: 43790, meanIndividual: 55180, costOfLivingIndex: 113, stateTaxRate: "0% (3% on dividends/interest)", minWage: 7.25, topEmployers: ["Dartmouth-Hitchcock", "Fidelity Investments", "BAE Systems"], topIndustries: ["Technology", "Healthcare", "Tourism"], intro: "New Hampshire has no state income tax on wages — it taxes only dividends and interest at 3%, and even that narrow tax is scheduled to phase out entirely. Combined with no state sales tax, New Hampshire is one of only two US states (the other is Alaska) with neither major consumption tax nor wage-based income tax. The $90,845 median household income ranks in the top ten in the US, driven in part by Massachusetts-commuter households living in southern NH and working in Boston's tax-advantaged corridor. The cost-of-living index of 113 reflects housing costs that have risen quickly, particularly in the Seacoast and in the communities along I-93 within commuting range of Boston. The economy has shifted meaningfully over three decades — traditional manufacturing has declined, while a defence cluster (BAE Systems, Lockheed-adjacent suppliers), technology (Dyn/Oracle, Fidelity Investments' Merrimack campus), and healthcare (Dartmouth-Hitchcock anchoring the Upper Valley) have all grown. The $7.25/hour minimum wage remains at the federal floor. Property taxes are the highest in the US by effective rate — the direct consequence of the state's no-sales-tax, no-wage-tax structure. Detailed data follows." },
  { slug: "new-jersey", name: "New Jersey", abbr: "NJ", medianHousehold: 97126, medianIndividual: 45790, meanIndividual: 60010, costOfLivingIndex: 115, stateTaxRate: "1.4-10.75%", minWage: 15.49, topEmployers: ["RWJBarnabas Health", "Johnson & Johnson", "Prudential"], topIndustries: ["Pharmaceuticals", "Finance", "Technology"], intro: "New Jersey has one of the highest median household incomes in the US at $97,126 and also the highest effective property-tax rate in the country — two statistics that coexist uncomfortably and drive much of the state's politics. The economy is anchored by the pharmaceutical industry, which has the densest employment cluster in the US in central and northern New Jersey (Johnson & Johnson in New Brunswick, Merck in Rahway and other sites, Bristol-Myers Squibb in Lawrenceville, and dozens of smaller pharmaceutical and biotech firms across Middlesex and Union counties). The northeastern part of the state functions as a commuter economy into New York City — Hudson, Essex, and Bergen counties have among the highest household incomes in the state and the highest housing costs. The southern counties (Atlantic City, Cape May) have a very different economy driven by tourism and gaming. State income tax is steeply progressive, with a top marginal rate of 10.75% on income over $1 million — among the highest in the country. The $15.49/hour minimum wage is indexed to inflation. Property taxes average around 2.2% of home value, noticeably higher than any other state. Full breakdown follows." },
  { slug: "new-mexico", name: "New Mexico", abbr: "NM", medianHousehold: 58722, medianIndividual: 31120, meanIndividual: 42280, costOfLivingIndex: 94, stateTaxRate: "1.7-5.9%", minWage: 12.00, topEmployers: ["Sandia National Labs", "University of New Mexico", "Presbyterian Healthcare"], topIndustries: ["Federal/National Labs", "Oil & Gas", "Healthcare"], intro: "New Mexico's economy is structured around an unusual federal-research base: Sandia National Laboratories and Los Alamos National Laboratory are among the largest employers in the state, and together with Kirtland Air Force Base and White Sands Missile Range, federal-and-defence employment accounts for a significantly larger share of state GDP than in almost any other state. The $58,722 median household income is below the national average — the research-and-defence sector pays well but is geographically concentrated around Albuquerque and Los Alamos, while much of the rest of the state has a more traditional economy. The Permian Basin in the southeastern counties (Lea and Eddy) has driven enormous oil-and-gas revenue for state coffers since 2018, funding large increases in education and public-sector spending. The cost-of-living index of 94 is below the national average, and effective purchasing power is roughly middle-of-the-pack. State income tax ranges from 1.7% to 5.9% across six brackets, with a 2019 reform that added a higher bracket on incomes above $315,000. The $12/hour minimum wage is above the federal floor. Property taxes are low. Detailed salary and employment data follow." },
  { slug: "new-york", name: "New York", abbr: "NY", medianHousehold: 81386, medianIndividual: 43120, meanIndividual: 60850, costOfLivingIndex: 126, stateTaxRate: "4-10.9%", minWage: 16.00, topEmployers: ["NYC Health + Hospitals", "JPMorgan Chase", "Mount Sinai"], topIndustries: ["Finance", "Healthcare", "Technology"], intro: "New York State's $81,386 median household income hides a steep geographic divide: the downstate region (NYC metro, Long Island, Westchester) and upstate operate as effectively two different economies. A household earning the state median in Albany or Buffalo is comfortable; the same income in Manhattan sits below the threshold at which rent is considered affordable under HUD standards. The state cost-of-living index of 126 reflects New York City's outsized weight in the calculation, while upstate metros like Rochester and Syracuse run at or below the national average. State income tax brackets range from 4% to 10.9%, with an additional surtax on incomes above $5 million. New York City residents pay an additional city income tax of 3.078 to 3.876 percent on top of the state bracket — a detail that catches new arrivals from Jersey City or Long Island off guard. The $16/hour minimum wage (with the downstate region at $16.50) puts New York among the five highest state wage floors in the country. Dominant industries are finance (Wall Street and the buyside firms), healthcare (Mount Sinai, NYU Langone, NYC Health + Hospitals), and a technology sector that has grown steadily since the 2010s. The full income, tax, and employer breakdown follows." },
  { slug: "north-carolina", name: "North Carolina", abbr: "NC", medianHousehold: 66186, medianIndividual: 35000, meanIndividual: 46420, costOfLivingIndex: 96, stateTaxRate: "4.5%", minWage: 7.25, topEmployers: ["Duke University Health", "Bank of America", "Lowe's"], topIndustries: ["Banking", "Technology", "Healthcare"], intro: "North Carolina has become one of the most active growth states in the US over the past fifteen years, consistently gaining population from both the Northeast and the Rust Belt. The $66,186 median household income is slightly below the national average, but the cost-of-living index of 96 and the Research Triangle's wage premium in specific industries create pockets of genuinely high effective earning power. Charlotte is the second-largest banking hub in the country by assets — Bank of America is headquartered there, along with a major Wells Fargo presence and most of Truist's corporate operations. The Research Triangle (Raleigh, Durham, and Chapel Hill) is anchored by Duke, UNC, and NC State, and sits on one of the densest biotech and pharmaceutical employer bases outside Boston. The Piedmont and mountain regions are more traditional, with furniture, textiles (scaled down from their peak), and tobacco-adjacent agriculture. The flat 4.5% state income tax is scheduled to phase down toward 3.99% by 2026 under enacted law. The $7.25/hour minimum wage remains at the federal floor. Property taxes are relatively low by East Coast standards, and the state has no estate or inheritance tax. Full income, tax, and employment breakdown follows." },
  { slug: "north-dakota", name: "North Dakota", abbr: "ND", medianHousehold: 73959, medianIndividual: 38030, meanIndividual: 47320, costOfLivingIndex: 92, stateTaxRate: "0-1.95%", minWage: 7.25, topEmployers: ["Sanford Health", "Essentia Health", "Microsoft"], topIndustries: ["Energy", "Agriculture", "Healthcare"], intro: "North Dakota has the lowest top marginal state income tax of any state that taxes income — just 1.95% at the top bracket, and 0% at the lowest income level. That structure is made possible by oil-and-gas revenue from the Bakken Formation, which has generated billions in tax receipts since the shale boom began in the late 2000s. The $73,959 median household income is above the national average, and the cost-of-living index of 92 gives North Dakota residents strong effective purchasing power. Fargo is the largest metro and has become a surprisingly diverse economy — Microsoft has a major campus there, Doosan Bobcat's North American headquarters is in West Fargo, and Sanford Health is the largest private employer statewide. Outside of Fargo and Bismarck, the economy is agriculture and energy: wheat, soybeans, sunflowers, and the Bakken oil patch centred on Williston and Dickinson. The $7.25/hour minimum wage remains at the federal floor. Property taxes are modest. The state has a large Legacy Fund — a sovereign-wealth-style trust of oil-tax revenue — that stood at over $10 billion by 2024 and produces meaningful ongoing investment income for state operations. Full breakdown follows." },
  { slug: "ohio", name: "Ohio", abbr: "OH", medianHousehold: 65720, medianIndividual: 34310, meanIndividual: 44960, costOfLivingIndex: 90, stateTaxRate: "0-3.5%", minWage: 10.45, topEmployers: ["Cleveland Clinic", "Ohio State University", "Nationwide"], topIndustries: ["Healthcare", "Manufacturing", "Finance"], intro: "Ohio's $65,720 median household income is below the national average, but the state's 90 cost-of-living index means dollars stretch further here than in most states east of the Mississippi. Ohio completed a multi-year tax reform in 2023 and 2024 that collapsed the income tax into a top marginal rate of 3.5%, with the first $26,050 of taxable income exempted entirely — one of the more generous exemption thresholds in the country. The economy is a story of two recoveries. Legacy manufacturing (auto assembly around Lordstown, steel in Youngstown) has stabilised after a brutal 2000s and 2010s. Meanwhile Columbus and Cincinnati have become unlikely boom markets, driven in part by Intel's $20B semiconductor fab investment in Licking County and a fintech cluster around JPMorgan Chase's second-largest campus. Healthcare is the state's single largest employer cluster, anchored by the Cleveland Clinic — consistently ranked among the world's top hospitals and Ohio's largest private employer. The $10.45/hour minimum wage is adjusted annually for inflation under a 2006 constitutional amendment, with a lower $3.93 tipped wage. Property taxes run around the national median. Wage, cost-of-living, and industry data follow." },
  { slug: "oklahoma", name: "Oklahoma", abbr: "OK", medianHousehold: 61364, medianIndividual: 32020, meanIndividual: 42510, costOfLivingIndex: 87, stateTaxRate: "0.25-4.75%", minWage: 7.25, topEmployers: ["University of Oklahoma", "Integris Health", "Tinker AFB"], topIndustries: ["Oil & Gas", "Aerospace", "Agriculture"], intro: "Oklahoma's $61,364 median household income is below the national average, but the cost-of-living index of 87 — among the ten lowest in the country — gives households a reasonable effective purchasing-power position. The economy is built on oil and gas (Oklahoma City and Tulsa both host headquarters of major independent E&P companies — Devon Energy, Continental Resources, Williams), aerospace and defence (Tinker Air Force Base is the largest single-site employer in the state, with the Air Logistics Complex performing depot maintenance on the B-52, B-1, and KC-135 fleets), and agriculture (cattle, wheat). The state income tax ranges from 0.25% at the bottom bracket to 4.75% at the top, with periodic phase-down proposals in the legislature. The $7.25/hour minimum wage remains at the federal floor, and Oklahoma is one of a handful of states whose legislature has preempted local governments from setting their own higher minimum wages. Property taxes are low. Oklahoma has no estate or inheritance tax. The cultural and economic centre of gravity remains divided between Oklahoma City and Tulsa, which operate in many respects as independent metros with distinct industry mixes. Full data follows." },
  { slug: "oregon", name: "Oregon", abbr: "OR", medianHousehold: 76362, medianIndividual: 39000, meanIndividual: 50540, costOfLivingIndex: 113, stateTaxRate: "4.75-9.9%", minWage: 14.70, topEmployers: ["Providence Health", "Nike", "Intel"], topIndustries: ["Technology", "Healthcare", "Manufacturing"], intro: "Oregon is one of only five states with no state sales tax — a structural feature that shifts revenue onto an unusually progressive income tax with a top marginal rate of 9.9%. The $76,362 median household income is above the national average, but the cost-of-living index of 113 pushes effective purchasing power back toward the middle of the pack, driven overwhelmingly by Portland metro housing costs. The economy is defined by two anchor employers: Intel (which operates its largest semiconductor manufacturing campus in the world in Hillsboro, just west of Portland — often called the Silicon Forest) and Nike (headquartered in Beaverton, with a large corporate and design workforce in the metro). The Willamette Valley south of Portland has a different economy — Eugene is anchored by the University of Oregon and a small-scale manufacturing and food-processing base. Eastern Oregon is more traditional, with ranching, agriculture (wheat, hay), and timber. The $14.70/hour minimum wage is tiered by region — Portland metro has a higher floor above $15.95 and rural counties a lower one — and is indexed annually. Property taxes are constrained by Measure 50 (1997), which limits assessment growth. Full breakdown follows." },
  { slug: "pennsylvania", name: "Pennsylvania", abbr: "PA", medianHousehold: 73170, medianIndividual: 37840, meanIndividual: 49710, costOfLivingIndex: 96, stateTaxRate: "3.07%", minWage: 7.25, topEmployers: ["UPMC", "University of Pennsylvania", "Comcast"], topIndustries: ["Healthcare", "Education", "Technology"], intro: "Pennsylvania has one of the lowest flat-rate state income taxes in the country at 3.07%, and it is the only state whose flat rate is effectively constrained by the Uniformity Clause of its state constitution — meaning any change requires a politically costly amendment process. The $73,170 median household income sits close to the national average, and the cost-of-living index of 96 puts the state 4% below the national benchmark. That combination — modest income tax, reasonable cost of living — is what keeps Pennsylvania attractive even as it loses residents to faster-growing Sun Belt states. The economy is fragmented by geography. Philadelphia is dominated by healthcare, education, and pharmaceutical giants (UPMC competes with the University of Pennsylvania Health System for the largest-employer title statewide). Pittsburgh has successfully pivoted from steel to tech, healthcare, and robotics; UPMC alone employs over 90,000 people in the region. The central and northern counties lean toward manufacturing, agriculture, and natural gas extraction in the Marcellus Shale. The $7.25/hour minimum wage remains at the federal floor — a standing point of political tension — and bills to raise it to $15 move through the legislature every few years without passing. Property taxes vary widely by county. Detailed data follows." },
  { slug: "rhode-island", name: "Rhode Island", abbr: "RI", medianHousehold: 78017, medianIndividual: 38600, meanIndividual: 50890, costOfLivingIndex: 107, stateTaxRate: "3.75-5.99%", minWage: 15.00, topEmployers: ["Lifespan", "CVS Health", "Brown University"], topIndustries: ["Healthcare", "Defense", "Education"], intro: "Rhode Island is the smallest state by area in the US, and that compactness shapes its economy — Providence's employment market effectively covers the entire state within a thirty-minute drive. The $78,017 median household income is above the national average, and the cost-of-living index of 107 is modestly above it. Healthcare (Lifespan and Care New England are the two largest hospital systems), higher education (Brown University, Providence College, Rhode Island School of Design, Johnson & Wales), and defence (General Dynamics Electric Boat's Quonset Point facility and the Naval Undersea Warfare Center) dominate employment. CVS Health is headquartered in Woonsocket and is one of the largest private employers in the state. The economy has historically lagged the rest of New England in post-recession recovery cycles, but the past five years have shown stronger growth. State income tax has three brackets from 3.75% to 5.99% — more moderate than Connecticut's or Massachusetts's. The $15/hour minimum wage is indexed. Property taxes are moderate by Northeast standards. Rhode Island has both an estate tax and a higher share of retiree residents than the US average. Full salary and employment breakdown follows." },
  { slug: "south-carolina", name: "South Carolina", abbr: "SC", medianHousehold: 63623, medianIndividual: 32350, meanIndividual: 42640, costOfLivingIndex: 94, stateTaxRate: "0-6.5%", minWage: 7.25, topEmployers: ["Prisma Health", "BMW", "Boeing"], topIndustries: ["Manufacturing", "Tourism", "Military"], intro: "South Carolina has become one of the most active foreign-direct-investment destinations in the US — BMW's Spartanburg plant is now the automaker's largest factory in the world by output, Boeing assembles the 787 Dreamliner in North Charleston, and Volvo, Mercedes-Benz Vans, and Michelin all operate major facilities in the state. That manufacturing base, combined with a $7.25/hour minimum wage at the federal floor and a right-to-work labour framework, has drawn consistent investment over three decades. The $63,623 median household income is below the national average, but the cost-of-living index of 94 gives households reasonable effective purchasing power. Charleston, Columbia, and Greenville are the three economic centres — Charleston's tourism-and-port economy is distinct from the Upstate's manufacturing cluster around Greenville-Spartanburg, which in turn is distinct from Columbia's state-government and insurance economy. The state income tax was reformed in 2023 and 2024 and currently ranges from 0 to 6.5%, with a path toward 6% under enacted legislation. Military employment is significant — Joint Base Charleston, Shaw AFB, Fort Jackson, and Parris Island Marine Recruit Depot collectively employ thousands. Property taxes are low. Full data follows." },
  { slug: "south-dakota", name: "South Dakota", abbr: "SD", medianHousehold: 69457, medianIndividual: 34510, meanIndividual: 43070, costOfLivingIndex: 92, stateTaxRate: "0%", minWage: 11.20, topEmployers: ["Sanford Health", "Avera Health", "Citigroup"], topIndustries: ["Healthcare", "Finance", "Agriculture"], intro: "South Dakota has no state income tax, and the state has unusually strong personal-asset-protection trust laws that have made it one of the most important onshore trust jurisdictions in the US — a significant portion of dynasty trusts and wealth-planning vehicles in the country are domiciled in South Dakota. The $69,457 median household income is close to the national average, and the cost-of-living index of 92 gives households solid effective purchasing power. Sioux Falls is the economic centre by a wide margin; the relocation of Citigroup's credit-card operations there in the 1980s (enabled by a 1980 state law removing interest-rate caps) launched what is now one of the largest credit-card processing and banking-back-office clusters in the country. Sanford Health is the largest private employer and one of the largest rural healthcare systems in the US. Rapid City and the Black Hills region have a different economy driven by tourism and federal employment (Ellsworth AFB, national parks and monuments). The $11.20/hour minimum wage is indexed to inflation. Property taxes are moderate. Agriculture (cattle, corn, soybeans) remains a major part of the rural economy. Full breakdown follows." },
  { slug: "tennessee", name: "Tennessee", abbr: "TN", medianHousehold: 64035, medianIndividual: 33830, meanIndividual: 44820, costOfLivingIndex: 91, stateTaxRate: "0%", minWage: 7.25, topEmployers: ["Vanderbilt University Medical", "FedEx", "HCA Healthcare"], topIndustries: ["Healthcare", "Logistics", "Music & Entertainment"], intro: "Tennessee has no state income tax on wages — the old Hall Tax on dividends and interest was fully phased out in 2021, making Tennessee's earned-income tax structure identical to Florida's and Texas's. The $64,035 median household income is below the national average, but the cost-of-living index of 91 means effective purchasing power is stronger than the wage number suggests. The economy has three distinct anchors. Nashville has been one of the fastest-growing metros in the US over the past decade, driven by healthcare (HCA Healthcare is the largest for-profit hospital chain in the US, headquartered in Nashville), the music industry, and a rapidly growing corporate-relocation footprint. Memphis is the logistics capital of the country by several measures — FedEx's global hub at Memphis International is the largest cargo airport in the Western Hemisphere, and Memphis is also the second-largest inland port on the Mississippi. East Tennessee (Knoxville, Chattanooga) has a different mix — manufacturing, the Volkswagen plant in Chattanooga, and Oak Ridge National Laboratory. The $7.25/hour minimum wage remains at the federal floor. Property taxes are low. Tennessee has no estate or inheritance tax. Full data follows." },
  { slug: "texas", name: "Texas", abbr: "TX", medianHousehold: 73035, medianIndividual: 35890, meanIndividual: 48710, costOfLivingIndex: 93, stateTaxRate: "0%", minWage: 7.25, topEmployers: ["H-E-B", "Texas Health Resources", "AT&T"], topIndustries: ["Energy", "Technology", "Healthcare"], intro: "Texas has no state income tax — a fact that consistently shows up in migration surveys as the single biggest draw for relocating professionals and remote workers. The $73,035 median household income ranks around the middle of US states, but that number goes much further in Texas than in most coastal markets: the statewide cost-of-living index of 93 runs 7% below the national average, and metros like San Antonio and El Paso are meaningfully cheaper still. The trade-off is that Texas compensates for the lack of income tax with above-average property taxes — effective rates sit around 1.6 to 1.9 percent depending on the county, among the highest in the country. The state minimum wage stays at the federal $7.25 floor, so low-end wage growth depends entirely on market forces; in practice, tight labour markets in Austin, Dallas, and Houston have pushed actual starting wages well above that figure. The economy is a three-legged stool: energy (still the largest single export category), technology (Austin's corporate migration of the past decade), and healthcare (the Texas Medical Center in Houston is the largest in the world). The full breakdown of income, employment, and tax context for Texas follows." },
  { slug: "utah", name: "Utah", abbr: "UT", medianHousehold: 86833, medianIndividual: 36360, meanIndividual: 46940, costOfLivingIndex: 101, stateTaxRate: "4.65%", minWage: 7.25, topEmployers: ["Intermountain Health", "Brigham Young University", "University of Utah"], topIndustries: ["Technology", "Healthcare", "Tourism"], intro: "Utah has one of the youngest median ages of any US state and one of the highest birth rates, and both facts shape the economy in distinctive ways. The $86,833 median household income is well above the national average, supported by the rapid growth of the Silicon Slopes tech cluster along the Wasatch Front between Salt Lake City and Provo. Qualtrics, Pluralsight, Ancestry.com, and Adobe's large Lehi campus are among the better-known employers, but the broader SaaS-and-fintech ecosystem has produced more unicorns per capita than most states. The cost-of-living index of 101 sits roughly at the national average, though Wasatch Front housing costs have risen meaningfully since 2018. Healthcare (Intermountain Health is one of the largest not-for-profit systems in the country) and tourism (Utah's national parks draw more than fifteen million visitors per year) round out the top employment sectors. The state income tax is a flat 4.65% — one of the lower flat rates in the West. The $7.25/hour minimum wage remains at the federal floor. Property taxes are low. The southern Utah counties (St. George, Moab) have their own distinct tourism-and-retirement-driven economies. Full breakdown follows." },
  { slug: "vermont", name: "Vermont", abbr: "VT", medianHousehold: 71084, medianIndividual: 37430, meanIndividual: 46150, costOfLivingIndex: 115, stateTaxRate: "3.35-8.75%", minWage: 14.15, topEmployers: ["University of Vermont Medical", "GlobalFoundries", "Dealer.com"], topIndustries: ["Healthcare", "Manufacturing", "Tourism"], intro: "Vermont is the second-smallest state by population, and that scale makes its economic statistics sensitive to the trajectory of a handful of large employers. The $71,084 median household income is below the national average, and the cost-of-living index of 115 pushes effective purchasing power meaningfully below nominal wages — Vermont is more expensive than its income levels suggest, driven by heating costs, grocery prices, and Chittenden County housing. The University of Vermont Medical Center anchors healthcare employment statewide, and GlobalFoundries' Essex Junction fab (acquired from IBM in 2015) is one of the largest private employers. Tourism — primarily skiing in winter and leaf-peeping and outdoor recreation in summer and autumn — is a significant share of the economy, particularly in Stowe, Killington, and the Mad River Valley. State income tax has four brackets ranging from 3.35% to 8.75%. The $14.15/hour minimum wage is indexed. Property taxes are high by New England standards. Vermont has both an estate tax and unusually progressive transfer taxes. Burlington is the only urban core of any meaningful scale and increasingly functions as the state's economic gravity centre. Full data follows." },
  { slug: "virginia", name: "Virginia", abbr: "VA", medianHousehold: 87249, medianIndividual: 42350, meanIndividual: 55710, costOfLivingIndex: 104, stateTaxRate: "2-5.75%", minWage: 12.41, topEmployers: ["Inova Health", "Amazon (HQ2)", "Booz Allen Hamilton"], topIndustries: ["Federal Government", "Technology", "Defense"], intro: "Virginia's $87,249 median household income is in the top ten in the US, driven by the federal and federal-contractor employment concentrated in Northern Virginia. Fairfax, Arlington, and Loudoun counties together contain one of the densest high-income white-collar workforces in the country: Amazon's HQ2 in Arlington, the Pentagon just across the Potomac, the intelligence-community cluster (CIA in Langley, DHS headquarters), and hundreds of defence and IT contractors (Booz Allen, Leidos, SAIC, CACI, Raytheon subsidiaries) all anchor the region. Loudoun County is home to the world's largest concentration of data-centre capacity — Ashburn handles a significant share of US internet traffic. The rest of Virginia is very different: Richmond has an insurance and finance economy (Capital One, Altria), the Hampton Roads region is a major military hub (Norfolk Naval Station is the largest naval base in the world), and the Shenandoah Valley is agricultural. The state income tax ranges from 2% to 5.75% across four brackets. The $12.41/hour minimum wage is indexed and was raised via 2020 legislation. Property taxes are moderate. Virginia has no estate or inheritance tax. Full data follows." },
  { slug: "washington", name: "Washington", abbr: "WA", medianHousehold: 90325, medianIndividual: 44830, meanIndividual: 58310, costOfLivingIndex: 114, stateTaxRate: "0% (7% on capital gains >$262K)", minWage: 16.66, topEmployers: ["Amazon", "Microsoft", "Boeing"], topIndustries: ["Technology", "Aerospace", "Healthcare"], intro: "Washington has no state income tax on wages, but it became one of the first US states to impose a capital-gains tax (7% on gains over $262,000 per year as of 2024), a novel structure that was upheld by the state supreme court in 2023. The $90,325 median household income ranks in the top ten, driven primarily by the tech cluster anchored by Microsoft in Redmond, Amazon in Seattle (Amazon is the state's largest private employer by headcount), and the dense supplier ecosystem around those two companies. Boeing remains one of the largest single-site manufacturing employers in the state (Everett and Renton). Outside of King County, the economy is very different: agriculture dominates eastern Washington (apples, wheat, wine), the Tri-Cities region has a major federal-research footprint (Hanford, Pacific Northwest National Laboratory), and the Puget Sound naval bases provide significant military employment. The cost-of-living index of 114 is driven overwhelmingly by Seattle-area housing. The $16.66/hour minimum wage is the highest state minimum wage in the country (Seattle's local minimum is even higher, above $20 for large employers). Property taxes are moderate. Full breakdown follows." },
  { slug: "west-virginia", name: "West Virginia", abbr: "WV", medianHousehold: 51248, medianIndividual: 29520, meanIndividual: 38940, costOfLivingIndex: 84, stateTaxRate: "2.36-5.12%", minWage: 8.75, topEmployers: ["WVU Medicine", "Charleston Area Medical", "Walmart"], topIndustries: ["Energy", "Healthcare", "Tourism"], intro: "West Virginia has the second-lowest median household income in the US at $51,248, and the lowest population-growth rate of any state over the past fifty years — the state has been the only one to have lost population in every decade since 1950. The cost-of-living index of 84 is the lowest in the country, which partially offsets the wage gap in purchasing-power terms. The economy has historically been built on coal, and the decline of that industry since the 1990s is the single largest factor behind the state's demographic trajectory. Natural gas extraction in the Marcellus Shale counties (Doddridge, Harrison, Marshall) has partially offset coal's decline but employs far fewer workers. The healthcare sector — led by WVU Medicine based in Morgantown — is now the largest employer cluster. State income tax has five brackets from 2.36% to 5.12%, with the top rate reduced meaningfully in 2023 reforms. The $8.75/hour minimum wage is slightly above the federal floor. Property taxes are among the lowest in the country. Tourism in the eastern panhandle and along the New River Gorge has grown since the gorge's 2020 national-park designation. Full breakdown follows." },
  { slug: "wisconsin", name: "Wisconsin", abbr: "WI", medianHousehold: 72458, medianIndividual: 36070, meanIndividual: 46280, costOfLivingIndex: 93, stateTaxRate: "3.54-7.65%", minWage: 7.25, topEmployers: ["Aurora Health Care", "Epic Systems", "Marshfield Clinic"], topIndustries: ["Manufacturing", "Healthcare", "Agriculture"], intro: "Wisconsin's $72,458 median household income is slightly above the national average, and the cost-of-living index of 93 gives households reasonably strong effective purchasing power. The economy is surprisingly diverse for a state often labelled agricultural. Milwaukee anchors a financial-services and industrial cluster (Northwestern Mutual, Harley-Davidson, Rockwell Automation, Johnson Controls headquarters). Madison is one of the fastest-growing knowledge-economy markets in the Midwest, driven by the University of Wisconsin, state government, and most notably Epic Systems — the electronic health records company based in Verona that has grown to more than 13,000 employees and handles records for over half of US healthcare interactions. Agriculture remains economically meaningful (Wisconsin leads the US in cheese production and is second in overall dairy output). State income tax ranges from 3.54% to 7.65% across four brackets. The $7.25/hour minimum wage remains at the federal floor — Wisconsin is unusual among Midwestern states in not having raised its floor above federal levels. Property taxes are moderate. Wisconsin has no estate or inheritance tax. The Fox Valley, around Appleton and Green Bay, is a separate manufacturing-and-paper-industry economy with its own labour market dynamics. Full data follows." },
  { slug: "wyoming", name: "Wyoming", abbr: "WY", medianHousehold: 72495, medianIndividual: 36710, meanIndividual: 46230, costOfLivingIndex: 95, stateTaxRate: "0%", minWage: 7.25, topEmployers: ["University of Wyoming", "Cheyenne Regional Medical", "State of Wyoming"], topIndustries: ["Mining & Energy", "Tourism", "Agriculture"], intro: "Wyoming is the least-populated state in the US and has no state income tax — a combination that has made the state unusually attractive for high-net-worth residency relocation over the past decade. The $72,495 median household income is near the national average, and the cost-of-living index of 95 puts effective purchasing power slightly above baseline. The economy is dominated by the energy sector in ways no other state matches: Wyoming is the largest coal-producing state in the country (Powder River Basin mines produce nearly half of all US coal), and the state is also a major producer of natural gas, uranium (Wyoming has the largest US uranium reserves), and trona. That energy-tax base funds most of state government and part of the reason income tax has never been introduced. Tourism anchored by Yellowstone and Grand Teton is significant in the northwestern counties. The $7.25/hour minimum wage is technically subordinate to the federal rate (the state minimum is still $5.15 on the books), but the federal rate applies to virtually all employers. Property taxes are among the lowest in the country. Wyoming also has unusually favourable LLC and trust laws, which contributes meaningfully to the state's high-asset residency profile. Full breakdown follows." },
];

export function getStateBySlug(slug: string): StateSalary | undefined {
  return statesSalary.find((s) => s.slug === slug);
}
